/**
 * Extracts the majority month from Column C (index 2) across all sheets.
 */
export const findMajorityMonth = (sheets: RosterSheet[]): string | null => {
  const monthCounts: Record<string, number> = {};

  sheets.forEach((sheet) => {
    sheet.data.forEach((row, index) => {
      if (index === 0) return; // Skip headers
      const dateVal = row[2]; // Column C
      if (dateVal) {
        const d = new Date(dateVal);
        if (!isNaN(d.getTime())) {
          const monthKey = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
          monthCounts[monthKey] = (monthCounts[monthKey] || 0) + 1;
        }
      }
    });
  });

  let maxCount = 0;
  let majority: string | null = null;

  Object.entries(monthCounts).forEach(([month, count]) => {
    if (count > maxCount) {
      maxCount = count;
      majority = month;
    }
  });

  return majority;
};

/**
 * Main cleaning logic:
 * 1. Filter by majority month in Column C.
 * 2. Keep columns A-H (indices 0-7).
 * 3. Keep rows 1-72 (indices 0-71).
 * 4. Delete tabs with no data rows.
 */
export const cleanRosterData = (sheets: RosterSheet[], majorityMonth: string): RosterSheet[] => {
  const processedSheets = sheets.map((sheet) => {
    // 1. Truncate rows (row 73 and below removed => indices 0 to 71 kept)
    let truncatedRows = sheet.data.slice(0, 72);

    // 2. Filter by majority month in Column C
    const cleanedRows = truncatedRows.filter((row, index) => {
      if (index === 0) return true; // Keep headers

      const dateVal = row[2];
      if (!dateVal) return false;

      const d = new Date(dateVal);
      if (isNaN(d.getTime())) return false;

      const rowMonth = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
      return rowMonth === majorityMonth;
    });

    // 3. Delete Column I and beyond (Keep A-H, indices 0-7)
    const columnCleanedRows = cleanedRows.map((row) => {
      const truncated = row.slice(0, 8);
      // Ensure row always has 8 items so index 5 (Col F) is accessible
      while (truncated.length < 8) truncated.push(null);
      return truncated;
    });

    return {
      ...sheet,
      data: columnCleanedRows,
    };
  });

  // 4. Delete tabs with no data rows (header only tabs)
  return processedSheets.filter(sheet => sheet.data.length > 1);
};

/**
 * Updates names in Column F (index 5) of the Roster.
 * Staff List Interpretation:
 * - Column A: Target Name (Correct Name).
 * - Column B (Optional): Search Key (Old name, nickname, or ID).
 * 
 * If Column B exists, we match Roster F against Staff B.
 * If Column B is missing, we match Roster F against Staff A (case correction).
 */
export const updateNames = (rosterSheets: RosterSheet[], staffList: any[][]): RosterSheet[] => {
  const nameMap: Record<string, string> = {};

  // Build a map from Staff List
  staffList.forEach((row) => {
    if (!row || row.length === 0) return;

    const correctName = row[0]; // Staff List Column A
    const searchKey = row.length > 1 ? row[1] : row[0]; // Column B if exists, else Column A

    if (correctName !== null && correctName !== undefined) {
      const targetVal = String(correctName).trim();
      const keyStr = searchKey !== null && searchKey !== undefined 
        ? String(searchKey).trim().toLowerCase() 
        : targetVal.toLowerCase();

      if (keyStr) {
        nameMap[keyStr] = targetVal;
      }
    }
  });

  return rosterSheets.map((sheet) => ({
    ...sheet,
    data: sheet.data.map((row, rIdx) => {
      if (rIdx === 0 || !row) return row; // Skip header

      const newRow = [...row];
      const originalName = newRow[5]; // Column F

      if (originalName !== null && originalName !== undefined) {
        const lookupKey = String(originalName).trim().toLowerCase();
        // If the roster name exists in our map, update it to the master list's version.
        if (nameMap[lookupKey]) {
          newRow[5] = nameMap[lookupKey];
        }
      }

      return newRow;
    }),
  }));
};

/**
 * Exports processed data back to an Excel file while keeping original tabs.
 */
export const exportToExcel = (sheets: RosterSheet[], fileName: string) => {
  const wb = XLSX.utils.book_new();
  sheets.forEach((sheet) => {
    const ws = XLSX.utils.aoa_to_sheet(sheet.data);
    XLSX.utils.book_append_sheet(wb, ws, sheet.name);
  });
  XLSX.writeFile(wb, fileName);
};

import * as XLSX from 'xlsx';
import { RosterSheet } from '../types';

/**
 * Parses an Excel or CSV file into a collection of sheets with raw data.
 * Filters for tabs named strictly in yyyymmdd format for rosters.
 */
export const parseExcel = async (file: File): Promise<RosterSheet[]> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });

        const isCsv = file.name.toLowerCase().endsWith('.csv');
        const rosterTabPattern = /^\d{8}$/;
        const hasRosterTabs = workbook.SheetNames.some(name => rosterTabPattern.test(name.trim()));

        let targetSheetNames = workbook.SheetNames;
        // If it looks like a roster (has yyyymmdd tabs), filter them.
        if (hasRosterTabs && !isCsv) {
          targetSheetNames = workbook.SheetNames.filter(name => rosterTabPattern.test(name.trim()));
        }

        const sheets: RosterSheet[] = targetSheetNames.map((name) => {
          const worksheet = workbook.Sheets[name];
          // raw: false ensures we get formatted strings directly
          // defval: null ensures indices stay consistent
          const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1, raw: false, defval: null }) as any[][];
          return { name, data: jsonData };
        });
        resolve(sheets);
      } catch (err) {
        reject(err);
      }
    };
    reader.onerror = reject;
    reader.readAsArrayBuffer(file);
  });
};

/**
 * Extracts the majority month from Column C (index 2) across all sheets.
 */
export const findMajorityMonth = (sheets: RosterSheet[]): string | null => {
  const monthCounts: Record<string, number> = {};

  sheets.forEach((sheet) => {
    sheet.data.forEach((row, index) => {
      if (index === 0) return; // Skip headers
      const dateVal = row[2]; // Column C
      if (dateVal) {
        const d = new Date(dateVal);
        if (!isNaN(d.getTime())) {
          const monthKey = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
          monthCounts[monthKey] = (monthCounts[monthKey] || 0) + 1;
        }
      }
    });
  });

  let maxCount = 0;
  let majority: string | null = null;

  Object.entries(monthCounts).forEach(([month, count]) => {
    if (count > maxCount) {
      maxCount = count;
      majority = month;
    }
  });

  return majority;
};

/**
 * Main cleaning logic:
 * 1. Filter by majority month in Column C.
 * 2. Keep columns A-H (indices 0-7).
 * 3. Keep rows 1-72 (indices 0-71).
 * 4. Increment all dates in Column C by 1 day.
 * 5. Delete tabs with no data rows.
 */
export const cleanRosterData = (sheets: RosterSheet[], majorityMonth: string): RosterSheet[] => {
  const processedSheets = sheets.map((sheet) => {
    // Truncate to row 72 (index 0-71)
    let truncatedRows = sheet.data.slice(0, 72);

    // Filter by majority month
    const cleanedRows = truncatedRows.filter((row, index) => {
      if (index === 0) return true; // Keep headers

      const dateVal = row[2];
      if (!dateVal) return false;

      const d = new Date(dateVal);
      if (isNaN(d.getTime())) return false;

      const rowMonth = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
      return rowMonth === majorityMonth;
    });

    // Truncate to Column H and Increment dates by 1 day
    const finalizedRows = cleanedRows.map((row, index) => {
      const truncated = row.slice(0, 8);
      // Ensure row has 8 items
      while (truncated.length < 8) truncated.push(null);

      // Apply +1 day to Column C (index 2) for data rows
      if (index > 0 && truncated[2]) {
        const d = new Date(truncated[2]);
        if (!isNaN(d.getTime())) {
          d.setDate(d.getDate() + 1);
          // Format back to a readable string (YYYY-MM-DD or original style)
          truncated[2] = d.toLocaleDateString('en-CA'); // YYYY-MM-DD format
        }
      }

      return truncated;
    });

    return {
      ...sheet,
      data: finalizedRows,
    };
  });

  // Remove tabs with only header or no rows
  return processedSheets.filter(sheet => sheet.data.length > 1);
};

