      const nameStr = String(fullName).trim();
      if (nameStr) {
        masterNameMap[nameStr.toLowerCase()] = nameStr;
      }
    }
  });

  return rosterSheets.map((sheet) => ({
    ...sheet,
    data: sheet.data.map((row, rIdx) => {
      if (rIdx === 0 || !row) return row; // Skip header

      const newRow = [...row];
      const currentName = newRow[5]; // Column F

      if (currentName !== null && currentName !== undefined) {
