      const d = new Date(dateVal);
      if (isNaN(d.getTime())) return false;

      const rowMonth = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
      return rowMonth === majorityMonth;
    });

    // Truncate to Column H
    const finalizedRows = cleanedRows.map((row) => {
      const truncated = row.slice(0, 8);
      // Ensure row has 8 items
      while (truncated.length < 8) truncated.push(null);
      return truncated;
    });

    return {
      ...sheet,
      data: finalizedRows,
    };
  });

  // Remove tabs with only header or no rows
  return processedSheets.filter(sheet => sheet.data.length > 1);
};

/**
 * Updates names in Column F (index 5) of the Roster.
 * Uses Staff List Column A as the source of Full Names.
 * Implements flexible matching:
 * 1. Exact match (case-insensitive).
 * 2. Partial match (If roster name is a substring of a staff full name).
 */
export const updateNames = (rosterSheets: RosterSheet[], staffList: any[][]): RosterSheet[] => {
  // Extract all non-empty strings from Staff List Column A
  const staffFullNames = staffList
    .map(row => row && row[0])
    .filter(name => name !== null && name !== undefined)
    .map(name => String(name).trim())
    .filter(name => name.length > 0);

  return rosterSheets.map((sheet) => ({
    ...sheet,
    data: sheet.data.map((row, rIdx) => {
      if (rIdx === 0 || !row) return row; // Skip header

      const newRow = [...row];
      const currentRosterName = newRow[5]; // Column F

      if (currentRosterName !== null && currentRosterName !== undefined) {
        const rosterNameStr = String(currentRosterName).trim();
        const rosterNameLower = rosterNameStr.toLowerCase();

        if (rosterNameStr) {
          // 1. Try exact match first
          const exactMatch = staffFullNames.find(sn => sn.toLowerCase() === rosterNameLower);

          if (exactMatch) {
            newRow[5] = exactMatch;
          } else {
            // 2. Try partial match (roster name is part of staff name)
